import sys

def count_distinct_colors(arr, start, end):
    visited_colors = [False] * 24
    distinct_count = 0
    for i in range(start, end + 1):
        color = arr[i]
        if not visited_colors[color]:
            visited_colors[color] = True
            distinct_count += 1
    return distinct_count

def main():
    input_line = sys.stdin.readline().strip()
    a, b, l, r = map(int, input_line.split())
    l -= 1
    r -= 1
    total_ab = a + b
    repeat_count = 4
    pattern_array = [0] * (total_ab * repeat_count)
    offset_h = l // total_ab
    l -= offset_h * total_ab
    r -= offset_h * total_ab
    segment_count = (r - l + 1) // total_ab
    if segment_count > 2:
        r -= (segment_count - 2) * total_ab
    diff_val = max(a - b, 1)
    for rep_idx in range(repeat_count):
        for k in range(a - diff_val):
            pattern_array[total_ab * rep_idx + k] = k
        for k in range(diff_val):
            pattern_array[total_ab * rep_idx + a - diff_val + k] = (a - diff_val + k) if (rep_idx % 2 == 0) else (a + k)
    min_colors = a + a
    for shift_a_idx in range(1, diff_val + 1):
        for k in range(b):
            pattern_array[a + k] = pattern_array[a - shift_a_idx]
        for shift_b_idx1 in range(1, diff_val + 1):
            for k in range(b):
                pattern_array[total_ab + a + k] = pattern_array[total_ab + a - shift_b_idx1]
            for shift_b_idx2 in range(1, diff_val + 1):
                for k in range(b):
                    pattern_array[2 * total_ab + a + k] = pattern_array[2 * total_ab + a - shift_b_idx2]
                for shift_b_idx3 in range(1, diff_val + 1):
                    for k in range(b):
                        pattern_array[3 * total_ab + a + k] = pattern_array[3 * total_ab + a - shift_b_idx3]
                    min_colors = min(min_colors, count_distinct_colors(pattern_array, l, r))
    print(min_colors)

if __name__ == "__main__":
    main()

